const e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Een snelle alleen-lezen controle of de printer klaar is om een print te starten."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Opnieuw controleren"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Bezig met controleren..."}},ready:{t:0,b:{t:2,i:[{t:3}],s:"Klaar om te printen"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"Niet klaar om te printen"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"Printer is onbereikbaar"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper is gereed"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper is niet gereed (status: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Geen print bezig"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Er loopt al een print ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Alle assen zijn gehomed"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Assen niet gehomed ("},{t:4,k:"axes"},{t:3,v:"); een printstart homed meestal eerst"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Gids"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Gids voor pre-printcontrole"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Sluiten"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wat is de pre-printcontrole?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Een alleen-lezen blik op of de printer klaar is om te starten: er wordt nooit iets bewogen of gewijzigd, er wordt alleen gerapporteerd. Harde blokkades maken het oordeel rood; waarschuwingen informeren maar blokkeren niet."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wat er wordt gecontroleerd"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper is gereed (niet uitgeschakeld of in fout), er loopt nog geen print, en of de assen gehomed zijn (informatief, aangezien een printstart meestal eerst homed)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Woordenlijst"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper-status"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klippers eigen status - 'ready' betekent dat het verbonden en inactief is; 'shutdown' of 'error' betekent dat er niet geprint kan worden tot dit is opgelost."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"Homing"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Elke as naar zijn eindstop bewegen zodat de printer weet waar de toolhead zich bevindt. De meeste printstartroutines homen automatisch."}}}}}}};export{e as default};
